import {seed} from './data.js';
import {dashboardMarkup} from './dashboard.js';
import {validateScenario,parseInspectionCsv,reportData,reportHtml,reportCsv,downloadText} from './file-tools.js';

const KEY='garment-quality-intelligence-v1';
const clone=x=>JSON.parse(JSON.stringify(x));
let db;try{db={...clone(seed),...(JSON.parse(localStorage.getItem(KEY))||{})}}catch{db=clone(seed)}
let view='overview',selectedBatch='B-1042',inspectionFilter='All',traceInput='B-1042',scenario='Inspect + targeted rework',toastTimer;
let dashboardFilters={factory:'All',scope:'All',defect:'All'},scenarioIndex=[],selectedScenarioFile='01-baseline-seam.json';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Math.round(n).toLocaleString(),moneyUnit=n=>'$'+Number(n).toFixed(2),num=n=>Math.round(n).toLocaleString(), pct=n=>(Math.round(n*10)/10)+'%';
const persist=()=>localStorage.setItem(KEY,JSON.stringify(db));
const batch=id=>db.batches.find(b=>b.id===id),product=sku=>db.products.find(p=>p.sku===sku),order=id=>db.orders.find(o=>o.id===id);
const rate=i=>i.sample?i.defects/i.sample*100:0;
const datePlus=(d,days)=>{let x=new Date(d+'T00:00:00');x.setDate(x.getDate()+days);return x.toISOString().slice(0,10)};
const badge=(label,tone)=>`<span class="status ${tone||({Fail:'red',Hold:'red',Blocked:'red','In progress':'amber',Open:'amber',Monitor:'amber','Pending review':'amber',Pass:'green',Done:'green',Available:'green',Shipped:'blue',Delivered:'blue'}[label]||'gray')}"><span class="dot"></span>${esc(label)}</span>`;
function toast(t){let el=$('.toast');if(el)el.remove();el=document.createElement('div');el.className='toast';el.textContent=t;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3600)}
function setView(v){view=v;render();window.scrollTo({top:0,behavior:'smooth'})}
const nav=[['overview','◫','Overview'],['trace','◇','Traceability'],['quality','◉','Quality signals'],['investigate','⌕','Investigation'],['recovery','▤','Recovery planner'],['cost','◈','Cost intelligence'],['capa','☑','CAPA command'],['learning','✦','Learning & verification']];
function shell(content){$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">⌁</div><div><strong>GARMENT<br>INTELLIGENCE</strong><small>QUALITY OS</small></div></div><div class="side-label">Workspace</div><nav class="nav">${nav.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}"><span class="ico">${icon}</span>${label}</button>`).join('')}</nav><div class="side-case"><span class="eyebrow">Active incident</span><strong>${esc(db.incident.id)} · Side seam integrity</strong><small>${esc(db.incident.stage)} · ${db.actions.filter(a=>a.status!=='Done').length} open actions</small><div style="margin-top:12px">${badge(db.incident.closed?'Closed':'High severity',db.incident.closed?'green':'red')}</div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="mobile-menu" id="menu" aria-label="Open menu">☰</button><span class="crumb">WORKSPACE / <b>${esc(nav.find(n=>n[0]===view)?.[2])}</b></span></div><div class="top-right"><span class="top-pill">● &nbsp; SYNTHETIC DEMO DATA</span><span class="top-pill">14 OCT 2026</span><span class="avatar">NR</span></div></header><div class="content">${content}</div></main></div>`}
function head(kicker,title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`}
function kpi(label,value,sub,tone=''){return `<div class="card metric ${tone}"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}
function card(title,desc,body,extra=''){return `<section class="card pad"><div class="card-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${extra}</div>${body}</section>`}
function exposure(){const ref=batch(db.incident.referenceBatch||'B-1042')||db.batches[0],focus=db.incident.defectType||'Open seam',out=[];for(const b of db.batches){const records=db.inspections.filter(i=>i.batch===b.id&&i.type===focus);const complaints=db.complaints.filter(c=>c.batch===b.id&&c.category===focus);const failed=records.some(i=>i.disposition==='Fail');const sameEquipment=b.machine===ref.machine&&b.sku===ref.sku;const sameInput=b.fabric===ref.fabric||b.thread===ref.thread;let scope='Unrelated',reason='No shared product and process signal';if(b.id===ref.id||failed||complaints.length)scope='Confirmed';else if(sameEquipment||b.sku===ref.sku&&sameInput)scope='Precautionary';if(scope==='Confirmed')reason=b.id===ref.id?'Reference batch for incident':failed?'Failed '+focus+' inspection':'Customer complaints linked to '+focus;else if(sameEquipment)reason='Shared '+ref.machine+' and operation; different material lots';else if(sameInput&&b.sku===ref.sku)reason='Shared material lot, but different line and passing inspection';out.push({...b,scope,reason,records,complaints})}return out}
function alerts(){const groups={};for(const i of db.inspections){const k=i.type;groups[k]??={type:k,defects:0,sample:0,records:[]};groups[k].defects+=i.defects;groups[k].sample+=i.sample;groups[k].records.push(i.id)}return Object.values(groups).sort((a,b)=>b.defects-a.defects)}
function overview(){let exp=exposure(),confirmed=exp.filter(x=>x.scope==='Confirmed'),prec=exp.filter(x=>x.scope==='Precautionary'),affected=confirmed.reduce((s,b)=>s+b.inventory,0),shipped=confirmed.reduce((s,b)=>s+b.shipped,0),open=db.actions.filter(a=>a.status!=='Done').length;let total=db.inspections.reduce((s,i)=>s+i.sample,0),def=db.inspections.reduce((s,i)=>s+i.defects,0);return head('Operations intelligence','Quality command center','One live case connecting production, customers, cost and recovery.',`<button class="btn" data-action="reset">↺ Reset demo</button><button class="btn primary" data-view="capa">Open incident →</button>`)+`<div class="alert-banner"><div class="alert-icon">⚠</div><div><strong>Seam integrity signal requires action</strong><p>Open-seam failures on MG-7 connect B-1042 and B-1044; customer complaints also implicate shipped B-1038. B-1043 shares material but passed inspection.</p></div><button class="btn" data-view="trace">Review exposure</button></div><div class="grid cols-4">${kpi('Confirmed stock to contain',num(affected)+' units','Across '+confirmed.filter(b=>b.inventory).length+' inventory batches','red')}${kpi('Already shipped',num(shipped)+' units','Customer and logistics exposure','amber')}${kpi('Inspection defect rate',pct(def/total*100),num(def)+' defects / '+num(total)+' sampled','teal')}${kpi('Open CAPA actions',open,'1 containment complete · '+open+' to finish','blue')}</div><div class="grid wide-left" style="margin-top:17px"><div class="grid">${card('Defect trend · MG-7','Daily side-seam defect rate against 2.5% alert threshold',trendChart(),`<button class="link" data-view="quality">View signals →</button>`)}${card('At-risk production','Confirmed and precautionary scope remains distinct',`<div class="table-wrap"><table><thead><tr><th>Batch</th><th>Basis</th><th>Inventory</th><th>Shipped</th><th>Scope</th></tr></thead><tbody>${exp.filter(x=>x.scope!=='Unrelated').map(b=>`<tr class="clickable" data-batch="${b.id}" data-goto="trace"><td><strong>${b.id}</strong><br><span class="muted">${esc(b.line)} · ${esc(b.machine)}</span></td><td>${esc(b.reason)}</td><td>${num(b.inventory)}</td><td>${num(b.shipped)}</td><td>${badge(b.scope,b.scope==='Confirmed'?'red':'amber')}</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="grid">${card('Incident progression','Evidence gates control final closure',`<div class="steps">${['Detect','Contain','Investigate','Correct','Verify','Close'].map((x,i)=>`<span class="step ${i<2?'done':i===2?'current':''}">${x}</span>${i<5?'<span class="step-arrow">›</span>':''}`).join('')}</div><div class="divider"></div><div class="mini-list">${db.actions.slice(0,4).map(a=>`<div class="mini-item"><div class="mini-icon">${a.status==='Done'?'✓':'○'}</div><div><strong>${esc(a.title)}</strong><p>${esc(a.owner)} · due ${esc(a.due)}</p></div></div>`).join('')}</div><button class="btn" data-view="capa">Manage actions →</button>`)}${card('Decision snapshot','Capacity and commercial trade-offs',`<div class="mini-list"><div class="mini-item"><div class="mini-icon">▤</div><div><strong>Targeted inspection + rework</strong><p>Estimated 2,910 units to inspect · 73 inspector-hours</p></div></div><div class="mini-item"><div class="mini-icon">◈</div><div><strong>Expected exposure: ${money(14820)}</strong><p>Includes containment, failure and customer costs</p></div></div><div class="mini-item"><div class="mini-icon">◷</div><div><strong>Shipment cut-off: 18 Oct</strong><p>Recovery options show feasible completion and delay</p></div></div></div><button class="btn" data-view="recovery">Compare recovery →</button>`)}</div></div>`}
function trendChart(){let vals=[1.1,1.3,1.5,2.0,2.8,4.2,5.8,3.9],W=560,H=150,p=20,xy=vals.map((v,i)=>[p+i*(W-2*p)/(vals.length-1),H-18-v*19]);return `<svg class="chart" viewBox="0 0 580 190" role="img" aria-label="Defect trend rises above the 2.5 percent threshold"><line class="gridline" x1="20" x2="560" y1="40" y2="40"/><line class="gridline" x1="20" x2="560" y1="90" y2="90"/><line class="gridline" x1="20" x2="560" y1="140" y2="140"/><line class="threshold" x1="20" x2="560" y1="84.5" y2="84.5"/><text x="495" y="78">2.5% threshold</text><path class="area" d="M${xy.map(p=>p.join(' ')).join('L')} L${xy.at(-1)[0]} 150 L20 150Z"/><polyline class="line" points="${xy.map(p=>p.join(',')).join(' ')}"/>${xy.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/>`).join('')}${['03','05','07','09','10','11','12','13'].map((d,i)=>`<text x="${xy[i][0]-9}" y="177">${d} Oct</text>`).join('')}</svg><div class="callout"><strong>Signal:</strong> The defect rate crossed the threshold as MG-7 processed side seams. Review machine settings and returned garments before confirming cause.</div>`}
function trace(){let b=batch(selectedBatch)||db.batches[0],e=exposure(),confirmed=e.filter(x=>x.scope==='Confirmed'),prec=e.filter(x=>x.scope==='Precautionary');return head('Product genealogy','Traceability & exposure','Search from a batch, inspection, or complaint and follow the production chain.',`<button class="btn primary" data-action="contain">${db.incident.hold?'✓ Containment active':'Activate containment'}</button>`)+`<div class="grid wide-left"><div class="grid">${card('Start from any record','Try B-1042, INS-611, CMP-207, or another batch',`<div class="row"><div class="field" style="flex:1"><input id="trace-query" value="${esc(traceInput)}" aria-label="Traceability record ID" placeholder="Enter record ID"></div><button class="btn primary" data-action="trace-search">Trace →</button></div><p class="note">Links use explicit batch, order, material, production and shipment IDs. Shared inputs suggest review; they do not prove a defect.</p>`)}${card('Selected genealogy',`${b.id} · ${product(b.sku)?.name} · ${num(b.units)} units`,`<div class="genealogy"><div class="node-row"><div class="node"><small>Customer / order</small><strong>${esc(order(b.order)?.customer)} · ${esc(b.order)}</strong></div><div class="node"><small>SKU / style</small><strong>${esc(b.sku)} · ${esc(product(b.sku)?.style)}</strong></div><div class="node"><small>Factory / shift</small><strong>${esc(db.factories.find(f=>f.id===b.factory)?.name)} · ${esc(b.shift)}</strong></div></div><div class="arrow-down">↓</div><div class="node-row"><div class="node"><small>Fabric / dye lot</small><strong>${esc(b.fabric)} · ${esc(db.materials.find(m=>m.id===b.fabric)?.detail)}</strong></div><div class="node"><small>Thread / trim</small><strong>${esc(b.thread)} · ${esc(b.trim)}</strong></div><div class="node"><small>Cutting batch</small><strong>${esc(b.cutting)}</strong></div></div><div class="arrow-down">↓</div><div class="node-row"><div class="node hot"><small>Sewing operation</small><strong>${esc(b.sewing)} · ${esc(b.line)} · ${esc(b.machine)}</strong></div><div class="node"><small>Operator team / period</small><strong>${esc(b.team)} · ${esc(b.start)}–${esc(b.end)}</strong></div><div class="node"><small>Finishing / packing</small><strong>${esc(b.finishing)} · ${esc(b.packing)}</strong></div></div><div class="arrow-down">↓</div><div class="node-row"><div class="node"><small>Inspection evidence</small><strong>${db.inspections.filter(i=>i.batch===b.id).map(i=>i.id).join(', ')||'None recorded'}</strong></div><div class="node"><small>Inventory</small><strong>${num(b.inventory)} · ${esc(b.location)}</strong></div><div class="node"><small>Shipment</small><strong>${db.shipments.filter(s=>s.batch===b.id).map(s=>s.id+' '+s.status).join(', ')||'Not scheduled'}</strong></div></div></div>`)}${card('Batch exposure','Choose a batch to inspect its exact lineage',`<div class="grid cols-3">${e.filter(x=>x.scope!=='Unrelated').map(x=>`<div class="risk-card ${x.scope==='Confirmed'?'confirmed':'precaution'}"><div class="row between"><h3>${x.id}</h3>${badge(x.scope,x.scope==='Confirmed'?'red':'amber')}</div><p>${esc(x.reason)}</p><div class="foot"><span>${num(x.inventory)} stock · ${num(x.shipped)} shipped</span><button class="link" data-batch="${x.id}">Trace →</button></div></div>`).join('')}</div>`)}</div><div class="grid">${card('Exposure summary','Confirmed versus precautionary',`<div class="matrix"><div class="cell"><small>Confirmed batches</small><strong>${confirmed.length}</strong></div><div class="cell"><small>Precautionary</small><strong>${prec.length}</strong></div><div class="cell"><small>Stock on hold</small><strong>${num(confirmed.reduce((s,b)=>s+b.inventory,0))}</strong></div><div class="cell"><small>Already shipped</small><strong>${num(confirmed.reduce((s,b)=>s+b.shipped,0))}</strong></div></div><div class="divider"></div><div class="callout"><strong>Containment rule:</strong> Confirmed scope is based on failed inspection or matching customer complaints. Precautionary scope uses shared line, machine or input links and needs verification.</div>`)}${card('Immediate containment','The cause is still under investigation',`<div class="checkline"><input id="hold" type="checkbox" ${db.incident.hold?'checked':''}><label for="hold">Hold work in progress and quarantine confirmed finished stock</label></div><div class="checkline"><input id="block" type="checkbox" ${db.incident.shipmentBlock?'checked':''}><label for="block">Block unreleased shipment SHP-918</label></div><div class="checkline"><input type="checkbox" checked disabled><label>Inspect B-1044, sample B-1043, and review B-1038 returns</label></div><div class="divider"></div><p class="note">At 40 units per inspector-hour, 2,910 units need about 73 hours. Four inspectors and two stations need roughly 2.3 working days. More handling may add about 0.2% damage risk.</p><button class="btn" data-view="recovery">Plan capacity →</button>`)}${card('Related shipments','Physical and commercial destinations',`<div class="table-wrap"><table><thead><tr><th>Shipment</th><th>Batch</th><th>Units</th><th>Status</th></tr></thead><tbody>${db.shipments.filter(s=>e.find(b=>b.id===s.batch)?.scope!=='Unrelated').map(s=>`<tr><td><strong>${s.id}</strong></td><td>${s.batch}</td><td>${num(s.units)}</td><td>${badge(s.status)}</td></tr>`).join('')}</tbody></table></div>`)}</div></div>`}
function quality(){let list=db.inspections.filter(i=>inspectionFilter==='All'||i.stage===inspectionFilter),types=alerts(),max=Math.max(...types.map(x=>x.defects));return head('Quality early warning','Inspection & signals','Volume-adjusted defect rates, stage results, and customer-language signals.',`<button class="btn primary" data-action="show-inspection">+ Record inspection</button>`)+`<div class="grid cols-3">${kpi('Open seam DPU',pct(types.find(x=>x.type==='Open seam')?.defects/types.find(x=>x.type==='Open seam')?.sample*100||0),'Across sampled open-seam records','red')}${kpi('MG-7 first-pass yield','93.9%','Versus 98.7% on L-03','amber')}${kpi('Customer complaints',db.complaints.length,'2 linked to side-seam failure','blue')}</div><div class="grid wide-left" style="margin-top:17px"><div class="grid">${card('Inspection records','Filter by quality gate',`<div class="pill-tabs" style="margin-bottom:15px">${['All','Incoming material','In-line','End-line','Finishing','Final random','Pre-shipment','Warehouse'].map(x=>`<button data-filter="${esc(x)}" class="${inspectionFilter===x?'active':''}">${esc(x)}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>ID / date</th><th>Batch</th><th>Stage</th><th>Defect</th><th>Rate</th><th>Result</th></tr></thead><tbody>${list.map(i=>`<tr><td><strong>${i.id}</strong><br><span class="muted">${i.date}</span></td><td><button class="link" data-batch="${i.batch}" data-goto="trace">${i.batch}</button></td><td>${esc(i.stage)}</td><td>${esc(i.type)}<br><span class="muted">${esc(i.location)}</span></td><td>${pct(rate(i))}<br><span class="muted">${i.defects}/${i.sample}</span></td><td>${badge(i.disposition)}</td></tr>`).join('')||`<tr><td colspan="6" class="empty">No records at this stage yet.</td></tr>`}</tbody></table></div>`)}${card('Customer feedback','Human approval required for grouping and escalation',`<div class="mini-list">${db.complaints.map(c=>`<div class="mini-item"><div class="mini-icon">✉</div><div style="flex:1"><div class="row between"><strong>${c.id} · ${c.customer}</strong>${badge(c.decision,c.decision==='Pending review'?'amber':'green')}</div><p>“${esc(c.text)}”</p><p>${c.batch} · suggested: ${esc(c.category)} · ${esc(c.severity)}</p>${c.decision==='Pending review'?`<button class="link" data-action="approve-complaint" data-id="${c.id}">Approve classification</button>`:''}</div></div>`).join('')}</div>`)}</div><div class="grid">${card('Defect Pareto','Count adjusted for inspected volume in alerts',`<div class="bar-list">${types.slice(0,5).map(t=>`<div class="bar-row"><span>${esc(t.type)}</span><div class="progress"><span style="width:${t.defects/max*100}%"></span></div><b>${t.defects}</b></div>`).join('')}</div><div class="divider"></div><div class="callout"><strong>Alert A-17 · High confidence</strong><br>Open seam increased on MG-7. Evidence: INS-611, INS-613, CMP-207 and CMP-208. Verify machine setup and returned garments; material-lot linkage alone is insufficient.</div>`)}${card('Alert logic','Transparent rules and uncertainty',`<div class="mini-list"><div class="mini-item"><div class="mini-icon">1</div><div><strong>Rate above threshold</strong><p>Final and end-line open-seam rates exceed the 2.5% trigger.</p></div></div><div class="mini-item"><div class="mini-icon">2</div><div><strong>Repeated across batches</strong><p>Two failing batches share MG-7 despite different fabric and thread lots.</p></div></div><div class="mini-item"><div class="mini-icon">3</div><div><strong>Complaint corroboration</strong><p>Returned-garment review is still pending; complaint wording is a suggested category.</p></div></div></div>`)}${card('Record an inspection','New records update rates and exposure',`<form id="inspection-form" class="form-grid"><div class="field"><label>Batch</label><select name="batch">${db.batches.map(b=>`<option>${b.id}</option>`).join('')}</select></div><div class="field"><label>Stage</label><select name="stage">${['Incoming material','In-line','End-line','Finishing','Final random','Pre-shipment','Warehouse'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Defect</label><select name="type">${['Open seam','Broken stitch','Skipped stitch','Uneven stitching','Puckering','Measurement deviation','Shade variation','Fabric hole','Stain','Incorrect label','Trimming problem','Packing error'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Location</label><input name="location" required placeholder="e.g. side seam"></div><div class="field"><label>Sampled units</label><input name="sample" type="number" min="1" required value="100"></div><div class="field"><label>Defective units</label><input name="defects" type="number" min="0" required value="0"></div><div class="field"><label>Inspector</label><input name="inspector" required placeholder="Name"></div><div class="field"><label>Severity</label><select name="severity"><option>Major</option><option>Minor</option><option>Critical</option></select></div><div class="field full"><label>Evidence reference / notes</label><input name="evidence" placeholder="Photo set, report ID, or observation"></div><button class="btn primary full" type="submit">Save inspection</button></form>`)}</div></div>`}
function investigate(){return head('Structured root cause','Investigation workspace','Compare hypotheses against production and quality evidence; reviewers confirm conclusions.',`<button class="btn primary" data-view="capa">Review CAPA →</button>`)+`<div class="grid wide-left"><div class="grid">${card('Evidence map','Machine, material, shift and complaint comparisons',`<div class="table-wrap"><table><thead><tr><th>Comparison</th><th>Observed</th><th>Implication</th></tr></thead><tbody><tr><td><strong>MG-7 · L-04</strong></td><td>B-1042 5.8%, B-1044 3.9%, B-1038 complaints</td><td>${badge('Strong signal','red')}</td></tr><tr><td><strong>Shared FAB-462 / THR-088</strong></td><td>B-1043 passes at 0.9% on MG-3</td><td>${badge('Weak material case','green')}</td></tr><tr><td><strong>Different shifts</strong></td><td>Day and night batches on MG-7 fail</td><td>${badge('Shift alone unlikely','amber')}</td></tr><tr><td><strong>Defect location</strong></td><td>Side seam, 18–24 cm from hem</td><td>${badge('Consistent','blue')}</td></tr></tbody></table></div>`)}${card('5 Whys · working hypothesis','Editable conclusion remains unverified until evidence review',`<div class="timeline"><div class="timeline-item"><strong>Why did the seam open?</strong><p>Stitches lacked sufficient seam strength on affected shirts.</p></div><div class="timeline-item"><strong>Why was seam strength low?</strong><p>Skipped stitches and inconsistent thread tension occurred at side-seam sewing.</p></div><div class="timeline-item"><strong>Why did settings drift?</strong><p>MG-7 setup may have changed after maintenance; machine logs must confirm.</p></div><div class="timeline-item"><strong>Why was drift not caught earlier?</strong><p>In-line sampling detected skipped stitches but escalation was delayed.</p></div><div class="timeline-item"><strong>What system gap allowed recurrence?</strong><p>No signed setup verification after maintenance and no fast escalation trigger.</p></div></div><div class="divider"></div><form id="cause-form" class="stack"><div class="field"><label>Root-cause conclusion</label><textarea name="cause">${esc(db.incident.cause)}</textarea></div><div class="field"><label>Supporting evidence references</label><input name="evidence" value="${esc(db.incident.causeEvidence||'INS-608, INS-611, INS-613; MG-7 setup log pending')}" required></div><div class="field"><label>Responsible reviewer</label><input name="reviewer" value="${esc(db.incident.causeReviewer||'Factory quality manager')}" required></div><label class="checkline"><input type="checkbox" name="confirmed" ${db.incident.causeConfirmed?'checked':''}> Evidence verified; confirm cause</label><button class="btn primary" type="submit">Save investigation</button></form>`)}${card('Corrective-action options','Expected reduction is uncertain until measured',`<div class="table-wrap"><table><thead><tr><th>Intervention</th><th>Cost</th><th>Lead time</th><th>Expected reduction</th><th>Confidence</th></tr></thead><tbody>${db.interventions.map(i=>`<tr><td><strong>${esc(i.name)}</strong><br><span class="muted">${esc(i.safety)} · ${esc(i.sustainability)}</span></td><td>${money(i.cost)}</td><td>${i.days} d</td><td>${i.reduction}%</td><td>${i.confidence}%</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="grid">${card('Fishbone categories','Evidence and counterevidence',`<div class="mini-list">${[['Machine','MG-7 repeats across materials and shifts','red'],['Method','Post-maintenance setup sign-off missing','amber'],['Material','B-1043 passes with the same thread and fabric','green'],['People','Same team, different shifts; training check needed','amber'],['Measurement','Review pull-test consistency and AQL sampling','blue'],['Environment','No temperature anomaly recorded','gray']].map(([t,d,c])=>`<div class="mini-item"><div class="mini-icon">◇</div><div><strong>${t} ${badge(c==='green'?'Counterevidence':c==='red'?'Leading':'Review',c)}</strong><p>${d}</p></div></div>`).join('')}</div>`)}${card('Hypothesis tests','Verification steps before conclusion',`<div class="checkline">${badge('Pending','amber')} Pull-test samples from MG-7 versus MG-3.</div><div class="checkline">${badge('Pending','amber')} Inspect MG-7 tension and timing logs.</div><div class="checkline">${badge('Pending','amber')} Examine returned B-1038 garments.</div><div class="checkline">${badge('Available','green')} Compare B-1043 shared-lot control batch.</div><div class="divider"></div><p class="note">A repeated pattern supports prioritization. It does not establish causation without the physical and process checks above.</p>`)}</div></div>`}
function calcScenario(name,inputs){let units=name==='Full-batch rework'?4500:name==='Inspect + targeted rework'?2910:name==='Statistical related-batch sampling'?2250:name==='Replacement production'?3900:3000;let inspectRate=+inputs.inspectRate||40,inspectors=+inputs.inspectors||4,stations=+inputs.stations||2,reworkRate=+inputs.reworkRate||240,reworkLines=+inputs.reworkLines||1;let inspectionHours=name==='Replacement production'?40:units/inspectRate;let reworkUnits=name==='Full-batch rework'?4500:name==='Inspect + targeted rework'?Math.round(units*.058):name==='Statistical related-batch sampling'?Math.round(units*.04):name==='Replacement production'?0:Math.round(units*.06);let inspectionDays=inspectionHours/Math.min(inspectors,stations*2)/8;let reworkDays=reworkUnits/(reworkRate*reworkLines);let productionDays=name==='Replacement production'?3900/1100:0;let approvalDays=.5,packDays=.5;let totalDays=Math.ceil((inspectionDays+reworkDays+productionDays+approvalDays+packDays)*10)/10;let date=datePlus('2026-10-14',Math.ceil(totalDays)),delay=Math.max(0,Math.ceil((new Date(date)-new Date('2026-10-18'))/86400000));let cost=Math.round(inspectionHours*15+reworkUnits*2.6+productionDays*2800+units*.18+delay*900+(name==='Full-batch rework'?1800:0));return {name,units,inspectionHours,reworkUnits,inspectionDays,reworkDays,productionDays,totalDays,date,delay,cost,feasible:inspectors>0&&stations>0&&reworkLines>0}}
function recovery(){const inp=db.recoveryInputs||{inspectors:4,stations:2,inspectRate:40,reworkLines:1,reworkRate:240},names=['Inspect + targeted rework','Full-batch rework','Statistical related-batch sampling','Replacement production','Split shipment + approved line'],rows=names.map(n=>calcScenario(n,inp)),sel=rows.find(r=>r.name===scenario)||rows[0];return head('Capacity-constrained recovery','Recovery & delivery planner','Compare inspection, rework, replacement and shipment alternatives against available capacity.',`<button class="btn primary" data-action="save-scenario">Use selected plan</button>`)+`<div class="grid cols-4">${kpi('Units in selected plan',num(sel.units),'Inspection or production scope','blue')}${kpi('Inspector-hours',num(sel.inspectionHours),'At '+inp.inspectRate+' units / hour','teal')}${kpi('Estimated completion',sel.date,sel.totalDays+' working-day equivalent','amber')}${kpi('Shipment exposure',sel.delay?sel.delay+' days':'On time','18 Oct cut-off','red')}</div><div class="grid wide-left" style="margin-top:17px"><div class="grid">${card('Recovery options','Click an option to see schedule and cost',`<div class="grid cols-2">${rows.map(r=>`<div class="option ${scenario===r.name?'selected':''}" data-scenario="${esc(r.name)}"><div class="row between"><h3>${esc(r.name)}</h3>${badge(r.delay?'Delay '+r.delay+'d':'On time',r.delay?'amber':'green')}</div><p>${r.name==='Statistical related-batch sampling'?'Faster, but higher missed-defect risk':r.name==='Replacement production'?'Requires material and available production line':r.name==='Full-batch rework'?'High handling and unnecessary work risk':'Balances inspection with identified rework'}</p><div class="option-stats"><span><b>${money(r.cost)}</b> cost</span><span><b>${r.totalDays}d</b> recovery</span><span><b>${num(r.reworkUnits)}</b> rework</span></div></div>`).join('')}</div>`)}${card('Operational schedule',`${scenario} · sequential estimate from 14 Oct 2026`,`<div class="schedule">${[['Additional inspection',sel.inspectionDays,0],['Sorting & rework',sel.reworkDays,sel.inspectionDays],['Replacement production',sel.productionDays,sel.inspectionDays+sel.reworkDays],['Reinspection & approval',.5,sel.inspectionDays+sel.reworkDays+sel.productionDays],['Packing & shipment release',.5,sel.inspectionDays+sel.reworkDays+sel.productionDays+.5]].filter(x=>x[1]>0).map(([t,d,start])=>`<div class="schedule-row"><span>${t}</span><div class="track"><span style="--start:${Math.min(88,start/Math.max(sel.totalDays,1)*100)}%;--width:${Math.max(6,d/Math.max(sel.totalDays,1)*100)}%"></span></div><b>${d.toFixed(1)}d</b></div>`).join('')}</div><div class="divider"></div><div class="callout"><strong>${sel.delay?'Delivery risk':'Cut-off achievable'}:</strong> ${sel.delay?`The plan finishes ${sel.delay} day(s) after the shipment cut-off. Consider split shipment, extra approved capacity, or a revised customer date.`:'Estimated release precedes the shipment cut-off, subject to quality approval and material availability.'}</div>`)}</div><div class="grid">${card('Capacity inputs','Change resources to recalculate each option',`<form id="capacity-form" class="form-grid"><div class="field"><label>Inspectors</label><input name="inspectors" type="number" min="1" value="${inp.inspectors}"></div><div class="field"><label>Inspection stations</label><input name="stations" type="number" min="1" value="${inp.stations}"></div><div class="field"><label>Units / inspector-hour</label><input name="inspectRate" type="number" min="1" value="${inp.inspectRate}"></div><div class="field"><label>Approved rework lines</label><input name="reworkLines" type="number" min="1" value="${inp.reworkLines}"></div><div class="field full"><label>Rework units / line-day</label><input name="reworkRate" type="number" min="1" value="${inp.reworkRate}"></div><button class="btn primary full" type="submit">Recalculate plan</button></form><div class="divider"></div><p class="note">Assumes 8-hour shifts, sequential inspection and rework, half-day approval, and half-day packing. Material, skill, maintenance and cut-off approvals still require planner review.</p>`)}${card('Constraints & decision','Operational feasibility checklist',`<div class="checkline">${badge('4 available','blue')} Inspectors with two stations.</div><div class="checkline">${badge('1 line','blue')} MG-7 rework line; approved transfer possible.</div><div class="checkline">${badge('Available','green')} Thread and fabric for targeted repair.</div><div class="checkline">${badge('Required','amber')} Quality release before packing.</div><div class="checkline">${badge('18 Oct','red')} Shipment cut-off and customer approval.</div><div class="divider"></div><p class="note">Selected plan is saved to the incident and logged as a management decision input.</p>`)}</div></div>`}
function cost(){let c=db.costInputs||{prevention:1900,appraisal:3200,internal:5480,external:4240,recurrence:35,reduction:74};let total=+c.prevention + +c.appraisal + +c.internal + +c.external,acceptable=9200-Math.round(2400*.058+2100*.039),expected=(+c.internal + +c.external)*(+c.recurrence/100),avoided=expected*(+c.reduction/100),roi=(avoided-c.prevention)/c.prevention*100,payback=avoided?c.prevention/(avoided/12):0;return head('Commercial quality economics','Cost of poor quality','See prevention, appraisal, internal failure and external failure in one decision.',`<button class="btn" data-view="recovery">Recovery costs →</button>`)+`<div class="grid cols-4">${kpi('Total quality cost',money(total),'Order PO-7812','red')}${kpi('COPQ / acceptable unit',moneyUnit(total/acceptable),num(acceptable)+' estimated acceptable units','blue')}${kpi('Expected avoided loss',money(avoided),'At '+c.recurrence+'% recurrence probability','teal')}${kpi('Preventive ROI',pct(roi),payback.toFixed(1)+' months simple payback','amber')}</div><div class="grid wide-left" style="margin-top:17px"><div class="grid">${card('Four cost categories','Editable synthetic estimates for the current incident',`<div class="bar-list">${[['Prevention',c.prevention,'#72b596'],['Appraisal',c.appraisal,'#8fb5c9'],['Internal failure',c.internal,'#dfad75'],['External failure',c.external,'#d77b6e']].map(([n,v,color])=>`<div class="bar-row"><span>${n}</span><div class="progress"><span style="width:${v/Math.max(c.prevention,c.appraisal,c.internal,c.external)*100}%;background:${color}"></span></div><b>${money(v)}</b></div>`).join('')}</div><div class="divider"></div><div class="matrix"><div class="cell"><small>Prevention</small><strong>${money(c.prevention)}</strong></div><div class="cell"><small>Appraisal</small><strong>${money(c.appraisal)}</strong></div><div class="cell"><small>Internal failure</small><strong>${money(c.internal)}</strong></div><div class="cell"><small>External failure</small><strong>${money(c.external)}</strong></div></div>`)}${card('Sensitivity to recurrence','Annual expected avoided loss for the proposed intervention',`<div class="table-wrap"><table><thead><tr><th>Recurrence chance</th><th>Expected loss</th><th>Avoided at ${c.reduction}%</th><th>Net benefit</th></tr></thead><tbody>${[10,20,35,50,70].map(p=>{let loss=(+c.internal + +c.external)*p/100,save=loss*c.reduction/100;return `<tr><td><strong>${p}%</strong></td><td>${money(loss)}</td><td>${money(save)}</td><td>${money(save-c.prevention)}</td></tr>`}).join('')}</tbody></table></div><p class="note">Simple scenario analysis; recurrence probability and effectiveness are assumptions, not observed outcomes.</p>`)}${card('Supplier / factory total-cost view','The lowest unit price can carry higher quality losses',`<div class="table-wrap"><table><thead><tr><th>Source</th><th>Unit price</th><th>Quality loss / unit</th><th>Effective cost / unit</th></tr></thead><tbody><tr><td><strong>Dhaka Apparel Works</strong></td><td>$5.80</td><td>$1.61</td><td><strong>$7.41</strong></td></tr><tr><td><strong>Gazipur Stitch House</strong></td><td>$6.10</td><td>$0.42</td><td><strong>$6.52</strong></td></tr></tbody></table></div><p class="note">Illustrative comparison from synthetic cost assumptions; not a sourcing decision without matched product and order data.</p>`)}</div><div class="grid">${card('Decision assumptions','Change values to test the preventive investment',`<form id="cost-form" class="form-grid">${[['prevention','Prevention cost'],['appraisal','Appraisal cost'],['internal','Internal failure'],['external','External failure'],['recurrence','Recurrence probability %'],['reduction','Expected reduction %']].map(([k,l])=>`<div class="field"><label>${l}</label><input name="${k}" type="number" min="0" ${['recurrence','reduction'].includes(k)?'max="100"':''} value="${c[k]}"></div>`).join('')}<button class="btn primary full" type="submit">Update cost model</button></form>`)}${card('What the model includes','Audit-friendly calculation basis',`<div class="mini-list"><div class="mini-item"><div class="mini-icon">P</div><div><strong>Prevention</strong><p>Training, maintenance, standards and error proofing.</p></div></div><div class="mini-item"><div class="mini-icon">A</div><div><strong>Appraisal</strong><p>Incoming, in-line, final and extra inspection.</p></div></div><div class="mini-item"><div class="mini-icon">I</div><div><strong>Internal failure</strong><p>Sorting, rework, scrap, downtime and schedule disruption.</p></div></div><div class="mini-item"><div class="mini-icon">E</div><div><strong>External failure</strong><p>Claims, returns, expedited replacements and margin exposure.</p></div></div></div><div class="callout"><strong>Formula:</strong> Expected avoided loss = (internal + external failure) × recurrence probability × expected reduction. ROI = (avoided loss − prevention cost) / prevention cost.</div>`)}</div></div>`}
function closureGates(){return [{label:'Containment active',ok:db.incident.hold&&db.incident.shipmentBlock},{label:'Root cause confirmed with reviewer and evidence',ok:db.incident.causeConfirmed&&!!db.incident.causeEvidence&&!!db.incident.causeReviewer},{label:'Management approval recorded',ok:db.incident.approval},{label:'All required actions done with evidence',ok:db.actions.filter(a=>a.required).every(a=>a.status==='Done'&&a.evidence.trim())},{label:'30/60/90-day verification complete',ok:Object.values(db.incident.verification).every(Boolean)}]}
function capa(){let gates=closureGates(),done=gates.filter(g=>g.ok).length;return head('Cross-functional execution','CAPA command center','Contain, investigate, correct, verify and close with an auditable evidence trail.',`<button class="btn ${gates.every(g=>g.ok)?'lime':'primary'}" data-action="close">${db.incident.closed?'✓ Incident closed':'Request closure'}</button>`)+`<div class="grid cols-4">${kpi('Incident severity',db.incident.severity,'Opened '+db.incident.opened,'red')}${kpi('Action completion',db.actions.filter(a=>a.status==='Done').length+'/'+db.actions.length,'Required cross-functional actions','blue')}${kpi('Closure gates',done+'/'+gates.length,'Evidence required before release','amber')}${kpi('Case stage',db.incident.closed?'Closed':db.incident.stage,'Leader: '+db.incident.leader,'teal')}</div><div class="grid wide-left" style="margin-top:17px"><div class="grid">${card('Action register','Owner, deadline, status and evidence for each commitment',`<div class="table-wrap"><table><thead><tr><th>Action / function</th><th>Owner</th><th>Due</th><th>Status</th><th>Evidence</th><th></th></tr></thead><tbody>${db.actions.map(a=>`<tr><td><strong>${a.id} · ${esc(a.title)}</strong><br><span class="muted">${esc(a.type)} · ${esc(a.role)}</span></td><td>${esc(a.owner)}</td><td>${esc(a.due)}</td><td>${badge(a.status)}</td><td>${a.evidence?`<span class="evidence">${esc(a.evidence)}</span>`:'<span class="muted">Required</span>'}</td><td><button class="link" data-action="edit-action" data-id="${a.id}">Update</button></td></tr>`).join('')}</tbody></table></div><div class="divider"></div><form id="new-action-form" class="form-grid"><div class="field full"><label>New action</label><input name="title" required placeholder="Describe corrective or preventive action"></div><div class="field"><label>Owner</label><input name="owner" required placeholder="Person or team"></div><div class="field"><label>Due date</label><input name="due" type="date" required value="2026-10-20"></div><div class="field"><label>Type</label><select name="type"><option>Corrective</option><option>Preventive</option><option>Containment</option><option>Investigation</option></select></div><div class="field"><label>Function</label><input name="role" required placeholder="e.g. Sourcing"></div><button class="btn primary full" type="submit">Add action</button></form>`)}${card('Audit trail','Decisions and updates are preserved in this browser',`<div class="timeline">${(db.audit||[{time:'2026-10-13',text:'INC-026 opened from failed final inspection INS-611.'},{time:'2026-10-13',text:'B-1042 quarantined and SHP-918 blocked.'},{time:'2026-10-14',text:'Complaint CMP-207 linked to shipped B-1038.'}]).slice().reverse().map(a=>`<div class="timeline-item"><strong>${esc(a.time)}</strong><p>${esc(a.text)}</p></div>`).join('')}</div>`)}</div><div class="grid">${card('RACI & approval','Incident leadership across factory and customer teams',`<div class="table-wrap"><table><thead><tr><th>Workstream</th><th>Responsible</th><th>Accountable</th></tr></thead><tbody><tr><td>Containment</td><td>Factory quality</td><td>Production manager</td></tr><tr><td>Root cause</td><td>Sewing supervisor</td><td>Factory quality manager</td></tr><tr><td>Customer impact</td><td>Customer quality</td><td>Merchandising</td></tr><tr><td>Recovery</td><td>Logistics coordinator</td><td>Production manager</td></tr><tr><td>Effectiveness</td><td>Verification owner</td><td>Factory management</td></tr></tbody></table></div><div class="divider"></div><label class="checkline"><input id="approval" type="checkbox" ${db.incident.approval?'checked':''}> Management approves corrective plan and resources</label><p class="note">Demo approval is recorded locally. Production use requires authenticated roles and a server audit log.</p>`)}${card('Closure gates','Every gate must pass',`<div class="mini-list">${gates.map(g=>`<div class="mini-item"><div class="mini-icon">${g.ok?'✓':'!'}</div><div><strong>${esc(g.label)}</strong><p>${g.ok?'Evidence gate satisfied':'Pending; closure is blocked'}</p></div></div>`).join('')}</div><div class="divider"></div><button class="btn ${gates.every(g=>g.ok)?'lime':'primary'}" data-action="close">${db.incident.closed?'Closed':gates.every(g=>g.ok)?'Close incident':'Check closure readiness'}</button>`)}${card('Escalation status','Outstanding items requiring attention',`<div class="callout"><strong>${db.actions.filter(a=>a.status!=='Done').length} actions remain open.</strong> The recovery decision, factory commitment and verification evidence should be reviewed at the next incident meeting.</div><div class="divider"></div><button class="btn" data-view="learning">Open verification →</button>`)}</div></div>`}
function learning(){let v=db.incident.verification,baseline=5.8,post=+(db.postRate??1.1),reduction=(baseline-post)/baseline*100,decision=post<2.5&&v.d30?'Effective so far':post>=baseline?'Ineffective':v.d30?'Partially effective':'Insufficient evidence';return head('Learning & effectiveness','Verify the change','Monitor comparable production, customer complaints and adverse delivery effects over time.',`<button class="btn" data-view="investigate">Investigation →</button>`)+`<div class="grid cols-4">${kpi('Baseline defect rate',pct(baseline),'MG-7 prior to action','red')}${kpi('Post-action rate',pct(post),'User-entered verification sample','teal')}${kpi('Observed reduction',pct(reduction),'Compare matched style and line','blue')}${kpi('Current decision',decision,'30/60/90-day checks','amber')}</div><div class="grid wide-left" style="margin-top:17px"><div class="grid">${card('30 / 60 / 90-day checkpoints','Completion requires evidence, not a date alone',`<div class="grid cols-3">${[['d30','30 days','2026-11-13'],['d60','60 days','2026-12-13'],['d90','90 days','2027-01-12']].map(([key,label,d])=>`<div class="risk-card ${v[key]?'cleared':'precaution'}"><div class="row between"><h3>${label}</h3>${badge(v[key]?'Verified':'Pending',v[key]?'green':'amber')}</div><p>Due ${d}. Compare rate, first-pass yield, rework hours, complaints, COPQ and delivery.</p><button class="link" data-action="verify" data-id="${key}">${v[key]?'Reopen check':'Record evidence →'}</button></div>`).join('')}</div><div class="divider"></div><form id="verification-form" class="form-grid"><div class="field"><label>Post-action defect rate %</label><input name="postRate" type="number" step="0.1" min="0" max="100" value="${post}"></div><div class="field"><label>Verification evidence / sample</label><input name="evidence" value="${esc(db.verificationEvidence||'')}" placeholder="Batch IDs, units and period"></div><div class="field full"><label>Adverse effect or delivery note</label><input name="sideEffect" value="${esc(db.sideEffect||'')}" placeholder="e.g. slower throughput on approved line"></div><button class="btn primary full" type="submit">Save verification result</button></form>`)}${card('Institutional lessons','Retain failed assumptions and updated standards',`<div class="mini-list">${db.lessons.map(l=>`<div class="mini-item"><div class="mini-icon">✦</div><div><strong>${esc(l.title)}</strong><p>${esc(l.text)}</p><p>${esc(l.case)} · ${esc(l.date)}</p></div></div>`).join('')}</div><div class="divider"></div><form id="lesson-form" class="stack"><div class="field"><label>Lesson title</label><input name="title" required placeholder="What changed our understanding?"></div><div class="field"><label>Lesson and standard update</label><textarea name="text" required placeholder="Record assumption, outcome, and next inspection or training change"></textarea></div><button class="btn" type="submit">Add lesson</button></form>`)}</div><div class="grid">${card('Comparable measures','Check quality, cost and delivery together',`<div class="table-wrap"><table><thead><tr><th>Measure</th><th>Before</th><th>After</th></tr></thead><tbody><tr><td>Open-seam rate</td><td>5.8%</td><td>${pct(post)}</td></tr><tr><td>First-pass yield</td><td>92.4%</td><td>${pct(Math.min(99.9,92.4+reduction*.07))}</td></tr><tr><td>Rework hours / 1k</td><td>24</td><td>${Math.max(3,Math.round(24*(1-reduction/100)))}</td></tr><tr><td>Complaint rate / 1k</td><td>0.8</td><td>${v.d30?'0.3':'Pending'}</td></tr><tr><td>Delivery adherence</td><td>96%</td><td>${db.sideEffect?'Review':'Pending'}</td></tr></tbody></table></div><p class="note">After-values beyond defect rate are illustrative until matched production and delivery records are supplied.</p>`)}${card('Decision rule','Intervention can be reopened',`<div class="callout"><strong>${decision}.</strong> ${post>=baseline?'Defects have not improved. Reopen the root-cause investigation.':post<2.5&&v.d30?'Early quality improvement is visible. Continue 60/90-day monitoring and check delivery impact.':'Insufficient volume-adjusted follow-up has been recorded to standardize the change.'}</div><div class="divider"></div><button class="btn danger" data-action="reopen">Reopen investigation</button>`)}${card('Validation challenge set','Synthetic ground truth for objective tests',`<div class="mini-list"><div class="mini-item"><div class="mini-icon">✓</div><div><strong>Shared material, different outcome</strong><p>B-1043 shares FAB-462 / THR-088 but passes on MG-3.</p></div></div><div class="mini-item"><div class="mini-icon">✓</div><div><strong>Same failure, different inputs</strong><p>B-1044 fails on MG-7 with other material lots.</p></div></div><div class="mini-item"><div class="mini-icon">✓</div><div><strong>Late customer signal</strong><p>B-1038 complaint arrives after shipment and changes exposure.</p></div></div><div class="mini-item"><div class="mini-icon">✓</div><div><strong>Quality / delivery trade-off</strong><p>Full rework may reduce escape risk but miss cut-off.</p></div></div></div>`)}</div></div>`}
function traceDetail(){
  const b=batch(selectedBatch),p=db.processConditions.find(x=>x.batch===b.id),rolls=db.fabricRolls.filter(x=>x.batch===b.id);
  let conditions=p?'<p><b>Operation:</b> '+esc(p.operation)+' · <b>Machine:</b> '+esc(p.machine)+' · <b>Speed:</b> '+num(p.speed)+' rpm · <b>Humidity:</b> '+p.humidity+'%</p><p><b>Needle:</b> '+esc(p.needle)+' · <b>Tension:</b> '+esc(p.tension)+' · <b>Setup signed:</b> '+(p.setupSignoff?'Yes':'No')+'</p>':'<p class="note">No operation condition log was captured for this batch.</p>';
  let history=rolls.map(r=>'<p><b>'+esc(r.id)+'</b> · '+esc(r.lot)+' · '+num(r.meters)+' metres</p>').join('');
  history+=db.rework.filter(r=>r.batch===b.id).map(r=>'<p><b>'+esc(r.id)+'</b> · '+esc(r.operation)+' · '+r.units+' units · '+r.hours+' hours · '+money(r.cost)+' · '+esc(r.status)+'</p>').join('');
  return '<div class="grid cols-2" style="margin-top:17px">'+card('Production conditions','Operation-level record for selected batch',conditions)+card('Fabric roll & rework history','Physical lot slices and repair records',history||'<p class="note">No roll or rework record.</p>')+'</div>';
}
function validationPanel(){
  const gt=db.groundTruth,pred=exposure(),identified=new Set(pred.filter(x=>x.scope==='Confirmed').map(x=>x.id));
  const tp=gt.confirmed.filter(x=>identified.has(x)).length,fp=[...identified].filter(x=>!gt.confirmed.includes(x)).length,fn=gt.confirmed.filter(x=>!identified.has(x)).length;
  const precision=tp+fp?tp/(tp+fp)*100:0,recall=tp+fn?tp/(tp+fn)*100:0;
  const missed=pred.filter(x=>gt.confirmed.includes(x.id)&&!identified.has(x.id)).reduce((s,x)=>s+x.units,0);
  const falseHold=pred.filter(x=>identified.has(x.id)&&!gt.confirmed.includes(x.id)).reduce((s,x)=>s+x.inventory,0);
  let body='<div class="matrix"><div class="cell"><small>Batch precision</small><strong>'+pct(precision)+'</strong></div><div class="cell"><small>Batch recall</small><strong>'+pct(recall)+'</strong></div><div class="cell"><small>Missed affected units</small><strong>'+num(missed)+'</strong></div><div class="cell"><small>False hold units</small><strong>'+num(falseHold)+'</strong></div></div>';
  body+='<div class="divider"></div><p class="note">Ground truth: confirmed '+gt.confirmed.join(', ')+'; precautionary '+gt.precautionary.join(', ')+'. Planted cause: '+esc(gt.cause)+'. Add an inspection to challenge the trace engine.</p>';
  return '<div style="margin-top:17px">'+card('Synthetic validation scorecard','Known ground truth tests exposure decisions',body)+'</div>';
}
function dashboard(){return dashboardMarkup({db,exposure:exposure(),filters:dashboardFilters,manifest:scenarioIndex,selectedFile:selectedScenarioFile,esc,num,pct,money,badge,head,kpi,card,calcScenario})}
function render(){let page=({overview:dashboard,trace,quality,investigate,recovery,cost,capa,learning})[view]();if(view==='trace')page+=traceDetail();if(view==='learning')page+=validationPanel();shell(page);document.title='Garment Quality Intelligence'}
function log(text){db.audit??=[];db.audit.push({time:new Date().toISOString().slice(0,10),text});persist()}
document.addEventListener('click',e=>{const n=e.target.closest('[data-view],[data-batch],[data-filter],[data-scenario],[data-action],#menu');if(!n)return;if(n.id==='menu'){$('#sidebar').classList.toggle('open');return}if(n.dataset.batch){selectedBatch=n.dataset.batch;traceInput=selectedBatch;if(n.dataset.goto)setView(n.dataset.goto);else render();return}if(n.dataset.view){setView(n.dataset.view);return}if(n.dataset.filter){inspectionFilter=n.dataset.filter;render();return}if(n.dataset.scenario){scenario=n.dataset.scenario;render();return}let a=n.dataset.action,id=n.dataset.id;if(a==='reset'){if(confirm('Reset all demo edits and restore the test data?')){db=clone(seed);persist();view='overview';render();toast('Demo data restored')}return}if(a==='show-inspection'){$('#inspection-form')?.scrollIntoView({behavior:'smooth'});return}if(a==='trace-search'){let q=$('#trace-query').value.trim().toUpperCase(),b=batch(q)||batch(db.inspections.find(i=>i.id===q)?.batch)||batch(db.complaints.find(c=>c.id===q)?.batch);if(!b){toast('No matching batch, inspection, or complaint');return}selectedBatch=b.id;traceInput=q;render();toast('Trace resolved to '+b.id);return}if(a==='contain'){db.incident.hold=true;db.incident.shipmentBlock=true;log('Containment activated for confirmed scope.');render();toast('Containment active');return}if(a==='approve-complaint'){let c=db.complaints.find(x=>x.id===id);c.decision='Human reviewed';log(`${id} complaint classification approved by reviewer.`);render();toast('Classification approved');return}if(a==='save-scenario'){db.incident.selectedScenario=scenario;log(`Recovery scenario selected: ${scenario}.`);render();toast('Recovery plan saved to incident');return}if(a==='edit-action'){let x=db.actions.find(y=>y.id===id),status=prompt('Status: Open, In progress, or Done',x.status);if(status===null)return;status=status.trim();if(!['Open','In progress','Done'].includes(status)){toast('Use Open, In progress, or Done');return}let evidence=prompt('Evidence reference (required to complete)',x.evidence);if(evidence===null)return;if(status==='Done'&&!evidence.trim()){toast('Evidence is required to complete an action');return}x.status=status;x.evidence=evidence.trim();log(`${id} updated to ${status}; evidence: ${x.evidence||'pending'}.`);render();toast('Action updated');return}if(a==='close'){let gates=closureGates(),missing=gates.filter(g=>!g.ok);if(missing.length){toast('Closure blocked: '+missing[0].label);return}db.incident.closed=true;db.incident.stage='Closed';log('Incident closed after all evidence and effectiveness gates passed.');render();toast('Incident closed');return}if(a==='verify'){if(db.incident.verification[id]){db.incident.verification[id]=false;log(`${id} verification reopened.`);render();return}let evidence=prompt('Evidence reference for this checkpoint (batch IDs, sample size and dates)');if(!evidence?.trim()){toast('Verification evidence is required');return}db.incident.verification[id]=true;db.verificationEvidence=(db.verificationEvidence?db.verificationEvidence+'; ':'')+id+': '+evidence.trim();log(`${id} checkpoint verified with evidence: ${evidence.trim()}.`);render();toast('Checkpoint verified');return}if(a==='reopen'){db.incident.closed=false;db.incident.stage='Investigation';db.incident.causeConfirmed=false;log('Investigation reopened for new evidence or adverse effect.');setView('investigate');toast('Investigation reopened');return}});
document.addEventListener('change',e=>{if(e.target.id==='hold'||e.target.id==='block'){db.incident[e.target.id==='hold'?'hold':'shipmentBlock']=e.target.checked;log(`${e.target.id==='hold'?'Quality hold':'Shipment block'} ${e.target.checked?'activated':'removed'}.`);render()}if(e.target.id==='approval'){db.incident.approval=e.target.checked;log(`Management approval ${e.target.checked?'recorded':'withdrawn'}.`);render()}});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(f.id==='inspection-form'){let sample=+d.sample,defects=+d.defects;if(defects>sample){toast('Defective units cannot exceed sampled units');return}let id='INS-'+(620+db.inspections.length),disposition=defects/sample*100>2.5?'Fail':'Pass';db.inspections.unshift({id,batch:d.batch,stage:d.stage,date:new Date().toISOString().slice(0,10),sample,defects,type:d.type,location:d.location,severity:d.severity,threshold:2.5,inspector:d.inspector,operation:'Recorded inspection',disposition,evidence:d.evidence,notes:''});log(`${id} recorded for ${d.batch}: ${defects}/${sample} ${d.type}; ${disposition}.`);render();toast(`${id} saved · ${disposition}`);return}if(f.id==='cause-form'){db.incident.cause=d.cause.trim();db.incident.causeEvidence=d.evidence.trim();db.incident.causeReviewer=d.reviewer.trim();db.incident.causeConfirmed=!!d.confirmed&&!!d.evidence.trim()&&!!d.reviewer.trim();if(db.incident.causeConfirmed)db.incident.stage='Corrective action';log(`Investigation updated; cause ${db.incident.causeConfirmed?'confirmed':'remains provisional'}.`);render();toast('Investigation saved');return}if(f.id==='capacity-form'){db.recoveryInputs=Object.fromEntries(Object.entries(d).map(([k,v])=>[k,Math.max(1,+v)]));log('Recovery capacity assumptions updated.');render();toast('Recovery scenarios recalculated');return}if(f.id==='cost-form'){db.costInputs=Object.fromEntries(Object.entries(d).map(([k,v])=>[k,Math.max(0,+v)]));db.costInputs.recurrence=Math.min(100,db.costInputs.recurrence);db.costInputs.reduction=Math.min(100,db.costInputs.reduction);log('COPQ assumptions updated.');render();toast('Cost model updated');return}if(f.id==='new-action-form'){let id='ACT-'+String(db.actions.length+1).padStart(2,'0');db.actions.push({id,title:d.title.trim(),owner:d.owner.trim(),due:d.due,type:d.type,role:d.role.trim(),status:'Open',evidence:'',required:true});log(`${id} assigned to ${d.owner.trim()}.`);render();toast('Action added');return}if(f.id==='verification-form'){db.postRate=+d.postRate;db.verificationEvidence=d.evidence.trim();db.sideEffect=d.sideEffect.trim();log('Effectiveness measures updated.');render();toast('Verification results saved');return}if(f.id==='lesson-form'){let id='LES-'+String(db.lessons.length+1).padStart(2,'0');db.lessons.push({id,title:d.title.trim(),text:d.text.trim(),case:db.incident.id,date:new Date().toISOString().slice(0,10)});log(`${id} learning record added.`);render();toast('Lesson recorded');return}});
function activeReport(){const inputs=db.recoveryInputs||{inspectors:4,stations:2,inspectRate:40,reworkLines:1,reworkRate:240};return reportData(db,exposure(),dashboardFilters,calcScenario(db.incident.selectedScenario||'Inspect + targeted rework',inputs))}
function loadScenario(payload,label){db=validateScenario(payload,seed);selectedBatch=db.incident.referenceBatch||db.batches[0].id;traceInput=selectedBatch;scenario=db.incident.selectedScenario||'Inspect + targeted rework';dashboardFilters={factory:'All',scope:'All',defect:'All'};persist();view='overview';render();toast(label+' loaded')}
document.addEventListener('click',async e=>{
  const scope=e.target.closest('[data-dashboard-scope]');if(scope){dashboardFilters.scope=scope.dataset.dashboardScope;render();return}
  const defect=e.target.closest('[data-dashboard-defect]');if(defect){dashboardFilters.defect=defect.dataset.dashboardDefect;render();return}
  const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='choose-file'){$('#scenario-upload')?.click();return}
  if(action==='clear-filters'){dashboardFilters={factory:'All',scope:'All',defect:'All'};render();return}
  if(action==='download-report'){const report=activeReport();downloadText('garment-quality-report.html',reportHtml(report),'text/html');toast('HTML report downloaded');return}
  if(action==='download-csv'){const report=activeReport();downloadText('garment-quality-report.csv',reportCsv(report),'text/csv');toast('CSV report downloaded');return}
  if(action==='load-scenario'){
    const entry=scenarioIndex.find(x=>x.file===selectedScenarioFile);if(!entry){toast('Choose a scenario');return}
    try{const response=await fetch('./test-files/'+encodeURIComponent(entry.file));if(!response.ok)throw new Error('Scenario file unavailable');loadScenario(await response.json(),entry.title)}catch(error){toast('Could not load scenario: '+error.message)}return
  }
});
document.addEventListener('change',async e=>{
  if(e.target.id==='dashboard-factory'){dashboardFilters.factory=e.target.value;render();return}
  if(e.target.id==='dashboard-defect'){dashboardFilters.defect=e.target.value;render();return}
  if(e.target.id==='scenario-select'){selectedScenarioFile=e.target.value;return}
  if(e.target.id==='scenario-upload'){
    const file=e.target.files?.[0];if(!file)return;
    if(file.size>5*1024*1024){toast('Maximum upload size is 5 MB');return}
    try{
      const contents=await file.text();
      if(file.name.toLowerCase().endsWith('.json')){loadScenario(JSON.parse(contents),file.name)}
      else if(file.name.toLowerCase().endsWith('.csv')){const rows=parseInspectionCsv(contents,db);db.inspections.unshift(...rows);log(`${rows.length} inspection records imported from ${file.name}.`);render();toast(rows.length+' inspections imported')}
      else throw new Error('Use a .json scenario or .csv inspection file');
    }catch(error){toast('Upload failed: '+error.message)}
  }
});
render();
fetch('./test-files/index.json').then(r=>{if(!r.ok)throw Error('Manifest unavailable');return r.json()}).then(items=>{scenarioIndex=items;if(view==='overview')render()}).catch(()=>{scenarioIndex=[]});
